class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        ans = 0

        if n > k // 2:
            for i in range(1, k // 2 + 1):
                ans += i

            for i in range(1, n - (k // 2)):
                ans += (i + k)
        else:
            for i in range(1, n + 1):
                ans += i

        return ans

